describe('Optimistic UI Updates for Post Likes', () => {
  beforeEach(() => {
    cy.visit('/posts');
  });

  it('should optimistically update UI when liking a post and handle API success', () => {
    // Intercept the initial post fetch
    cy.intercept('GET', '/api/posts').as('getPosts');
    cy.wait('@getPosts');

    // Verify initial state: like button is not filled
    cy.get('[data-testid="like-button"]').should('not.have.attr', 'liked');
    cy.get('[data-testid="like-count"]').should('contain', '10');

    // Intercept the like API call
    cy.intercept('POST', '/api/posts/*/like', {
      statusCode: 200,
      body: { success: true, postId: '123', newLikeCount: 11 }
    }).as('likePost');

    // Click the like button
    cy.get('[data-testid="like-button"]').click();

    // Verify optimistic update: UI updates immediately before API response
    cy.get('[data-testid="like-button"]').should('have.attr', 'liked');
    cy.get('[data-testid="like-count"]').should('contain', '11');

    // Wait for API response
    cy.wait('@likePost');

    // Verify final state matches API response
    cy.get('[data-testid="like-button"]').should('have.attr', 'liked');
    cy.get('[data-testid="like-count"]').should('contain', '11');
  });

  it('should revert optimistic UI update when API call fails', () => {
    // Intercept the initial post fetch
    cy.intercept('GET', '/api/posts').as('getPosts');
    cy.wait('@getPosts');

    // Verify initial state
    cy.get('[data-testid="like-button"]').should('not.have.attr', 'liked');
    cy.get('[data-testid="like-count"]').should('contain', '10');

    // Intercept the like API call with failure
    cy.intercept('POST', '/api/posts/*/like', {
      statusCode: 500,
      body: { success: false, error: 'Server error' }
    }).as('likePostFailed');

    // Click the like button
    cy.get('[data-testid="like-button"]').click();

    // Verify optimistic update occurs immediately
    cy.get('[data-testid="like-button"]').should('have.attr', 'liked');
    cy.get('[data-testid="like-count"]').should('contain', '11');

    // Wait for failed API response
    cy.wait('@likePostFailed');

    // Verify UI reverts to original state after failure
    cy.get('[data-testid="like-button"]').should('not. have.attr', 'liked');
    cy.get('[data-testid="like-count"]').should('contain', '10');

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible').should('contain', 'Failed to like post');
  });
});
